//! SQL backend for PostgreSQL, MySQL (8.0+) and SQLite, built with SeaQuery.
//!
//! Three fixed tables; each entry stores one JSON document per stage holding
//! content fields plus system fields ([`Entry::view`]), so filtering and
//! sorting run in SQL. The few engine-specific expressions (reading typed
//! values out of JSON) live in [`Dialect`]; everything else is generated by
//! SeaQuery for the engine in use.

mod dialect;
mod filter;

use std::str::FromStr;
use std::time::Duration;

use async_trait::async_trait;
use tess_core::{CmsError, ContentType, Entry, EntryQuery, Page, Result, Stage, Storage};
use sea_query::{
    Alias, ColumnDef, Expr, ExprTrait, Index, MysqlQueryBuilder, OnConflict, PostgresQueryBuilder, Query,
    SqliteQueryBuilder, Table, TableCreateStatement,
};
use sea_query_sqlx::SqlxBinder;
use serde_json::{Map, Value};
use sqlx::Row;
use sqlx::types::Json;
use uuid::Uuid;

pub use dialect::Dialect;

const CONTENT_TYPES: &str = "tess_content_type";
const ENTRIES: &str = "tess_entry";
const SETTINGS: &str = "tess_setting";
/// Arbitrary constant identifying the Postgres migration advisory lock.
const MIGRATION_LOCK: i64 = 0x0063_6d73_5f6d_6967;

enum Pool {
    Postgres(sqlx::PgPool),
    MySql(sqlx::MySqlPool),
    Sqlite(sqlx::SqlitePool),
}

pub struct SqlStorage {
    pool: Pool,
    dialect: Dialect,
}

fn err(e: impl std::fmt::Display) -> CmsError {
    CmsError::storage(e)
}

/// Marks SeaQuery output as audited for sqlx. Safe because every value is a
/// bound parameter: identifiers are constants of this crate, and the custom
/// fragments of `dialect`/`filter` only contain constant SQL and placeholders
/// (field names, which come from users, are always bound).
fn audited(sql: String) -> sqlx::AssertSqlSafe<String> {
    sqlx::AssertSqlSafe(sql)
}

/// Runs `$body` with `$pool` bound to the concrete pool and `$qb` to the
/// constructor of the matching SeaQuery builder. The body is expanded once per engine.
macro_rules! with_pool {
    ($self:expr, |$pool:ident, $qb:ident| $body:expr) => {
        match &$self.pool {
            Pool::Postgres($pool) => {
                let $qb = || PostgresQueryBuilder;
                $body
            }
            Pool::MySql($pool) => {
                let $qb = || MysqlQueryBuilder;
                $body
            }
            Pool::Sqlite($pool) => {
                let $qb = || SqliteQueryBuilder;
                $body
            }
        }
    };
}

/// Executes a statement built by SeaQuery; returns affected rows.
macro_rules! execute {
    ($self:expr, $stmt:expr) => {
        with_pool!($self, |pool, qb| {
            let (sql, values) = $stmt.build_sqlx(qb());
            sqlx::query_with(audited(sql), values).execute(pool).await.map_err(err)?.rows_affected()
        })
    };
}

/// Fetches rows and maps each with `$map` (expanded per engine, so the row
/// type is concrete).
macro_rules! fetch {
    ($self:expr, $stmt:expr, |$row:ident| $map:expr) => {
        with_pool!($self, |pool, qb| {
            let (sql, values) = $stmt.build_sqlx(qb());
            sqlx::query_with(audited(sql), values)
                .fetch_all(pool)
                .await
                .map_err(err)?
                .iter()
                .map(|$row| $map)
                .collect::<Result<Vec<_>>>()?
        })
    };
}

/// Decodes an entry row.
macro_rules! entry_from_row {
    ($row:ident) => {
        entry_from_docs(
            $row.try_get::<String, _>("content_type").map_err(err)?,
            $row.try_get::<String, _>("id").map_err(err)?,
            $row.try_get::<Json<Value>, _>("draft").map_err(err)?.0,
            $row.try_get::<Option<Json<Value>>, _>("published").map_err(err)?.map(|j| j.0),
        )
    };
}

const ENTRY_COLUMNS: [&str; 4] = ["content_type", "id", "draft", "published"];

fn cols<const N: usize>(names: [&str; N]) -> [Alias; N] {
    names.map(Alias::new)
}

fn json<T: serde::de::DeserializeOwned>(v: Json<Value>) -> Result<T> {
    serde_json::from_value(v.0).map_err(err)
}

/// Rebuilds an entry from its stored per-stage documents.
fn entry_from_docs(content_type: String, id: String, draft: Value, published: Option<Value>) -> Result<Entry> {
    let as_map = |v: Value| -> Result<Map<String, Value>> {
        match v {
            Value::Object(m) => Ok(m),
            _ => Err(CmsError::Storage("entry document is not an object".into())),
        }
    };
    let id = Uuid::parse_str(&id).map_err(err)?;
    let published = published.filter(|p| !p.is_null()).map(as_map).transpose()?;
    Entry::from_views(content_type, id, as_map(draft)?, published).map_err(CmsError::Storage)
}

impl SqlStorage {
    /// Connects from a URL: `postgres://…`, `mysql://…` or
    /// `sqlite://path/to/file.db` (created if missing).
    pub async fn connect(url: &str, max_connections: u32) -> Result<Self> {
        let dialect = Dialect::from_url(url).ok_or_else(|| {
            CmsError::Storage("DATABASE_URL must start with postgres://, mysql:// or sqlite://".into())
        })?;
        let pool = match dialect {
            Dialect::Postgres => Pool::Postgres(
                sqlx::postgres::PgPoolOptions::new().max_connections(max_connections).connect(url).await.map_err(err)?,
            ),
            Dialect::MySql => Pool::MySql(
                sqlx::mysql::MySqlPoolOptions::new().max_connections(max_connections).connect(url).await.map_err(err)?,
            ),
            Dialect::Sqlite => {
                let opts = sqlx::sqlite::SqliteConnectOptions::from_str(url)
                    .map_err(err)?
                    .create_if_missing(true)
                    .journal_mode(sqlx::sqlite::SqliteJournalMode::Wal)
                    .busy_timeout(Duration::from_secs(10));
                Pool::Sqlite(
                    sqlx::sqlite::SqlitePoolOptions::new()
                        .max_connections(max_connections)
                        .connect_with(opts)
                        .await
                        .map_err(err)?,
                )
            }
        };
        Ok(SqlStorage { pool, dialect })
    }

    pub fn dialect(&self) -> Dialect {
        self.dialect
    }

    /// Key column. Bytewise comparison on MySQL, whose default collations are
    /// case- and accent-insensitive (other backends treat `Post` and `POST`
    /// as different keys).
    fn key_column(&self, name: &str, len: u32) -> ColumnDef {
        let mut c = ColumnDef::new(Alias::new(name));
        c.string_len(len).not_null();
        if self.dialect == Dialect::MySql {
            c.extra("COLLATE utf8mb4_bin");
        }
        c
    }

    fn schema(&self) -> Vec<TableCreateStatement> {
        vec![
            Table::create()
                .table(Alias::new(CONTENT_TYPES))
                .if_not_exists()
                .col(self.key_column("api_id", 64).primary_key())
                .col(ColumnDef::new(Alias::new("definition")).json_binary().not_null())
                .to_owned(),
            Table::create()
                .table(Alias::new(ENTRIES))
                .if_not_exists()
                .col(self.key_column("content_type", 64))
                .col(self.key_column("id", 36))
                .col(ColumnDef::new(Alias::new("draft")).json_binary().not_null())
                .col(ColumnDef::new(Alias::new("published")).json_binary().null())
                .primary_key(Index::create().col(Alias::new("content_type")).col(Alias::new("id")))
                .to_owned(),
            Table::create()
                .table(Alias::new(SETTINGS))
                .if_not_exists()
                .col(self.key_column("setting_key", 255).primary_key())
                .col(ColumnDef::new(Alias::new("value")).json_binary().not_null())
                .to_owned(),
        ]
    }

    fn stage_column(stage: Stage) -> &'static str {
        match stage {
            Stage::Draft => "draft",
            Stage::Published => "published",
        }
    }

    fn entries_where(&self, content_type: &str, query: &EntryQuery) -> sea_query::Condition {
        let col = Self::stage_column(query.stage);
        let mut cond = sea_query::Cond::all()
            .add(Expr::col(Alias::new("content_type")).eq(content_type))
            .add(Expr::col(Alias::new(col)).is_not_null());
        if let Some(f) = &query.filter {
            cond = cond.add(filter::where_expr(self.dialect, col, f));
        }
        cond
    }
}

#[async_trait]
impl Storage for SqlStorage {
    fn name(&self) -> &'static str {
        match self.dialect {
            Dialect::Postgres => "postgres",
            Dialect::MySql => "mysql",
            Dialect::Sqlite => "sqlite",
        }
    }

    async fn migrate(&self) -> Result<()> {
        match &self.pool {
            // Concurrent cold starts (Lambda) must not race on DDL.
            Pool::Postgres(pool) => {
                let mut tx = pool.begin().await.map_err(err)?;
                sqlx::query("SELECT pg_advisory_xact_lock($1)")
                    .bind(MIGRATION_LOCK)
                    .execute(&mut *tx)
                    .await
                    .map_err(err)?;
                for t in self.schema() {
                    sqlx::query(audited(t.build(PostgresQueryBuilder))).execute(&mut *tx).await.map_err(err)?;
                }
                tx.commit().await.map_err(err)
            }
            Pool::MySql(pool) => {
                for t in self.schema() {
                    sqlx::query(audited(t.build(MysqlQueryBuilder))).execute(pool).await.map_err(err)?;
                }
                Ok(())
            }
            Pool::Sqlite(pool) => {
                for t in self.schema() {
                    sqlx::query(audited(t.build(SqliteQueryBuilder))).execute(pool).await.map_err(err)?;
                }
                Ok(())
            }
        }
    }

    async fn list_content_types(&self) -> Result<Vec<ContentType>> {
        let stmt = Query::select().column(Alias::new("definition")).from(Alias::new(CONTENT_TYPES)).to_owned();
        Ok(fetch!(self, stmt, |row| json(row.try_get::<Json<Value>, _>("definition").map_err(err)?)))
    }

    async fn get_content_type(&self, api_id: &str) -> Result<Option<ContentType>> {
        let stmt = Query::select()
            .column(Alias::new("definition"))
            .from(Alias::new(CONTENT_TYPES))
            .and_where(Expr::col(Alias::new("api_id")).eq(api_id))
            .to_owned();
        let rows: Vec<ContentType> =
            fetch!(self, stmt, |row| json(row.try_get::<Json<Value>, _>("definition").map_err(err)?));
        Ok(rows.into_iter().next())
    }

    async fn put_content_type(&self, content_type: &ContentType) -> Result<()> {
        let definition = serde_json::to_value(content_type).map_err(err)?;
        let stmt = Query::insert()
            .into_table(Alias::new(CONTENT_TYPES))
            .columns(cols(["api_id", "definition"]))
            .values_panic([content_type.api_id.clone().into(), definition.into()])
            .on_conflict(OnConflict::column(Alias::new("api_id")).update_column(Alias::new("definition")).to_owned())
            .to_owned();
        execute!(self, stmt);
        Ok(())
    }

    async fn delete_content_type(&self, api_id: &str) -> Result<()> {
        let entries = Query::delete()
            .from_table(Alias::new(ENTRIES))
            .and_where(Expr::col(Alias::new("content_type")).eq(api_id))
            .to_owned();
        let ct = Query::delete()
            .from_table(Alias::new(CONTENT_TYPES))
            .and_where(Expr::col(Alias::new("api_id")).eq(api_id))
            .to_owned();
        with_pool!(self, |pool, qb| {
            let mut tx = pool.begin().await.map_err(err)?;
            for stmt in [&entries, &ct] {
                let (sql, values) = stmt.build_sqlx(qb());
                sqlx::query_with(audited(sql), values).execute(&mut *tx).await.map_err(err)?;
            }
            tx.commit().await.map_err(err)?;
        });
        Ok(())
    }

    async fn get_entry(&self, content_type: &str, id: Uuid) -> Result<Option<Entry>> {
        let stmt = Query::select()
            .columns(cols(ENTRY_COLUMNS))
            .from(Alias::new(ENTRIES))
            .and_where(Expr::col(Alias::new("content_type")).eq(content_type))
            .and_where(Expr::col(Alias::new("id")).eq(id.to_string()))
            .to_owned();
        let rows: Vec<Entry> = fetch!(self, stmt, |row| entry_from_row!(row));
        Ok(rows.into_iter().next())
    }

    async fn put_entry(&self, entry: &Entry) -> Result<()> {
        let draft = Value::Object(entry.view(Stage::Draft).unwrap_or_default());
        let published: sea_query::Value = match entry.view(Stage::Published) {
            Some(v) => Value::Object(v).into(),
            None => sea_query::Value::Json(None),
        };
        let stmt = Query::insert()
            .into_table(Alias::new(ENTRIES))
            .columns(cols(ENTRY_COLUMNS))
            .values_panic([
                entry.content_type.clone().into(),
                entry.id.to_string().into(),
                draft.into(),
                published.into(),
            ])
            .on_conflict(
                OnConflict::columns(cols(["content_type", "id"])).update_columns(cols(["draft", "published"])).to_owned(),
            )
            .to_owned();
        execute!(self, stmt);
        Ok(())
    }

    async fn delete_entry(&self, content_type: &str, id: Uuid) -> Result<bool> {
        let stmt = Query::delete()
            .from_table(Alias::new(ENTRIES))
            .and_where(Expr::col(Alias::new("content_type")).eq(content_type))
            .and_where(Expr::col(Alias::new("id")).eq(id.to_string()))
            .to_owned();
        Ok(execute!(self, stmt) > 0)
    }

    async fn query_entries(&self, content_type: &str, query: &EntryQuery) -> Result<Page> {
        let cond = self.entries_where(content_type, query);
        let count = Query::select()
            .expr(Expr::cust("COUNT(*)"))
            .from(Alias::new(ENTRIES))
            .cond_where(cond.clone())
            .to_owned();
        let totals: Vec<i64> = fetch!(self, count, |row| row.try_get::<i64, _>(0).map_err(err));
        let total = std::cmp::max(totals.first().copied().unwrap_or(0), 0) as u64;

        let mut select = Query::select()
            .columns(cols(ENTRY_COLUMNS))
            .from(Alias::new(ENTRIES))
            .cond_where(cond)
            .limit(query.limit as u64)
            .offset(query.offset as u64)
            .to_owned();
        let col = Self::stage_column(query.stage);
        for (expr, order) in filter::order_exprs(self.dialect, col, &query.effective_sort()) {
            select.order_by_expr(expr, order);
        }
        let items: Vec<Entry> = fetch!(self, select, |row| entry_from_row!(row));
        Ok(Page { items, total })
    }

    async fn get_setting(&self, key: &str) -> Result<Option<Value>> {
        let stmt = Query::select()
            .column(Alias::new("value"))
            .from(Alias::new(SETTINGS))
            .and_where(Expr::col(Alias::new("setting_key")).eq(key))
            .to_owned();
        let rows: Vec<Value> = fetch!(self, stmt, |row| Ok(row.try_get::<Json<Value>, _>("value").map_err(err)?.0));
        Ok(rows.into_iter().next())
    }

    async fn put_setting(&self, key: &str, value: &Value) -> Result<()> {
        let stmt = Query::insert()
            .into_table(Alias::new(SETTINGS))
            .columns(cols(["setting_key", "value"]))
            .values_panic([key.into(), value.clone().into()])
            .on_conflict(OnConflict::column(Alias::new("setting_key")).update_column(Alias::new("value")).to_owned())
            .to_owned();
        execute!(self, stmt);
        Ok(())
    }

    async fn delete_setting(&self, key: &str) -> Result<bool> {
        let stmt = Query::delete()
            .from_table(Alias::new(SETTINGS))
            .and_where(Expr::col(Alias::new("setting_key")).eq(key))
            .to_owned();
        Ok(execute!(self, stmt) > 0)
    }

    async fn list_settings(&self, prefix: &str) -> Result<Vec<(String, Value)>> {
        // Settings are few: filter and sort in Rust, independent of collations.
        let stmt = Query::select().columns(cols(["setting_key", "value"])).from(Alias::new(SETTINGS)).to_owned();
        let mut rows: Vec<(String, Value)> = fetch!(self, stmt, |row| Ok((
            row.try_get::<String, _>("setting_key").map_err(err)?,
            row.try_get::<Json<Value>, _>("value").map_err(err)?.0,
        )));
        rows.retain(|(k, _)| k.starts_with(prefix));
        rows.sort_by(|a, b| a.0.cmp(&b.0));
        Ok(rows)
    }
}

#[cfg(test)]
mod tests {
    use std::sync::Arc;

    use super::*;

    #[tokio::test]
    async fn sqlite_conformance() {
        let dir = tempfile::tempdir().unwrap();
        let url = format!("sqlite://{}", dir.path().join("tess.db").display());
        let storage = SqlStorage::connect(&url, 4).await.unwrap();
        tess_core::testkit::run_conformance(Arc::new(storage)).await;
    }

    /// Runs against `TESS_TEST_POSTGRES_URL`; skipped when unset.
    #[tokio::test]
    async fn postgres_conformance() {
        let Ok(url) = std::env::var("TESS_TEST_POSTGRES_URL") else {
            eprintln!("TESS_TEST_POSTGRES_URL not set, skipping");
            return;
        };
        let storage = SqlStorage::connect(&url, 5).await.unwrap();
        tess_core::testkit::run_conformance(Arc::new(storage)).await;
    }

    /// Runs against `TESS_TEST_MYSQL_URL`; skipped when unset.
    #[tokio::test]
    async fn mysql_conformance() {
        let Ok(url) = std::env::var("TESS_TEST_MYSQL_URL") else {
            eprintln!("TESS_TEST_MYSQL_URL not set, skipping");
            return;
        };
        let storage = SqlStorage::connect(&url, 5).await.unwrap();
        tess_core::testkit::run_conformance(Arc::new(storage)).await;
    }
}
